const body = $input.first().json.body;

if (!body || typeof body !== 'object') {
  throw new Error('Payload invalide: body manquant');
}

const type = String(body.type || 'maintenance_preventive');
const requireField = (field) => {
  if (body[field] === undefined || body[field] === null || body[field] === '') {
    throw new Error('Payload invalide: champ manquant ' + field);
  }
};

if (type === 'module_install') {
  for (const field of ['device', 'device_name', 'firmware', 'mac', 'supla_server', 'email']) {
    requireField(field);
  }

  const sanitized = {
    type,
    reason: body.reason || 'client_consent',
    device: String(body.device).trim(),
    device_name: String(body.device_name).trim(),
    firmware: String(body.firmware).trim(),
    mac: String(body.mac).trim(),
    supla_server: String(body.supla_server).trim(),
    email: String(body.email).trim(),
    uptime_ms: Number(body.uptime_ms || body.uptime || 0),
  };

  return [{ json: { body: sanitized } }];
}

for (const field of ['device', 'heap']) {
  requireField(field);
}

if (isNaN(Number(body.heap))) {
  throw new Error('Payload invalide: heap doit etre un nombre');
}

const uptime = body.uptime_ms !== undefined ? body.uptime_ms : (body.uptime !== undefined ? body.uptime : 0);
if (uptime !== undefined && isNaN(Number(uptime))) {
  throw new Error('Payload invalide: uptime doit etre un nombre');
}

const sanitized = {
  type,
  reason: body.reason || 'heap_monitor',
  device: String(body.device).trim(),
  heap: Number(body.heap),
  heap_kb: body.heap_kb !== undefined ? Number(body.heap_kb) : Math.round((Number(body.heap) / 1024) * 100) / 100,
  threshold: body.threshold !== undefined ? Number(body.threshold) : null,
  uptime: Number(uptime) || 0,
  event: body.event || body.reason || 'status',
  status: body.status || null,
  max_block: (body.max_block !== undefined && body.max_block !== null) ? Number(body.max_block) : null,
  frag_pct: (body.frag_pct !== undefined && body.frag_pct !== null) ? Number(body.frag_pct) : null
};

return [{ json: { body: sanitized } }];

const body = $('Validate Payload').first().json.body;
const type = String(body.type || 'maintenance_preventive');
const timestamp = new Date().toISOString();
const sq = String.fromCharCode(39);
const esc = (value) => String(value ?? '').replace(/\\/g, '\\\\').replace(/'/g, "''");

if (type === 'module_install') {
  const device = String(body.device);
  const deviceName = String(body.device_name || '');
  const firmware = String(body.firmware || '');
  const mac = String(body.mac || '');
  const suplaServer = String(body.supla_server || '');
  const email = String(body.email || '');
  const uptime = Number(body.uptime_ms || 0);

  const sqlCreateTable = "CREATE TABLE IF NOT EXISTS heap_monitoring.module_installs (" +
    "id INT AUTO_INCREMENT PRIMARY KEY," +
    "timestamp DATETIME DEFAULT CURRENT_TIMESTAMP," +
    "device VARCHAR(64) NOT NULL," +
    "device_name VARCHAR(64)," +
    "firmware VARCHAR(32)," +
    "mac VARCHAR(32)," +
    "supla_server VARCHAR(128)," +
    "email VARCHAR(191)," +
    "uptime_ms BIGINT," +
    "reason VARCHAR(64)," +
    "UNIQUE KEY uniq_device_mac (device, mac)," +
    "KEY idx_module_installs_timestamp (timestamp)," +
    "KEY idx_module_installs_email (email)" +
    ")";

  const sqlInsert = "INSERT INTO heap_monitoring.module_installs " +
    "(device, device_name, firmware, mac, supla_server, email, uptime_ms, reason) VALUES (" +
    sq + esc(device) + sq + "," +
    sq + esc(deviceName) + sq + "," +
    sq + esc(firmware) + sq + "," +
    sq + esc(mac) + sq + "," +
    sq + esc(suplaServer) + sq + "," +
    sq + esc(email) + sq + "," +
    uptime + "," + sq + esc(body.reason || 'client_consent') + sq + ") " +
    "ON DUPLICATE KEY UPDATE timestamp=CURRENT_TIMESTAMP, device_name=VALUES(device_name), firmware=VALUES(firmware), supla_server=VALUES(supla_server), email=VALUES(email), uptime_ms=VALUES(uptime_ms), reason=VALUES(reason)";

  return [{ json: {
    type,
    device,
    device_name: deviceName,
    firmware,
    mac,
    supla_server: suplaServer,
    email,
    uptime,
    event: 'module_install',
    level: 'INFO',
    timestamp,
    telegramMsg: '[INSTALL] ' + device + ' - fiche installation recue\n' +
      'Module  : ' + deviceName + '\n' +
      'MAC     : ' + mac + '\n' +
      'SUPLA   : ' + suplaServer + '\n' +
      'Email   : ' + email + '\n' +
      'Version : ' + firmware + '\n' +
      'Heure   : ' + timestamp,
    alert: false,
    sqlCreateTable,
    sqlInsert,
  } }];
}

const heap = Number(body.heap);
const event = String(body.event || 'status');
const device = String(body.device);
const uptime = Number(body.uptime) || 0;
const max_block = (body.max_block !== undefined && body.max_block !== null) ? Number(body.max_block) : null;
const frag_pct = (body.frag_pct !== undefined && body.frag_pct !== null) ? Number(body.frag_pct) : null;

const totalSec = Math.floor(uptime / 1000);
const hh = Math.floor(totalSec / 3600);
const mm = Math.floor((totalSec % 3600) / 60);
const ss = totalSec % 60;
const uptimeStr = hh + ':' + String(mm).padStart(2, '0') + ':' + String(ss).padStart(2, '0');

let heap_effective = heap;
let note = '';
let level;

if (heap < 2500) {
  level = 'FATAL';
  note = 'heap brut < 2500B - OOM imminent';
} else if (event === 'boot' || event === 'cloud-ready') {
  level = 'INFO';
  note = 'event ' + event + ' - log informatif';
} else if (event === 'status') {
  heap_effective = heap + 2500;
  note = 'mesure HTTP corrigee +2500B';
  if (heap_effective >= 4500) level = 'INFO';
  else if (heap_effective >= 3500) level = 'WARNING';
  else if (heap_effective >= 3000) level = 'CRITICAL';
  else level = 'FATAL';
} else {
  if (heap >= 4500) level = 'INFO';
  else if (heap >= 3500) level = 'WARNING';
  else if (heap >= 3000) level = 'CRITICAL';
  else level = 'FATAL';
}

const requestedStatus = String(body.status || '').toUpperCase();
const requestedReason = String(body.reason || '').toLowerCase();
if (requestedStatus === 'FATAL') {
  level = 'FATAL';
  note = note ? note + ' / statut firmware FATAL' : 'statut firmware FATAL';
} else if (requestedStatus === 'CRITICAL' || requestedReason === 'heap_critical') {
  if (level !== 'FATAL') level = 'CRITICAL';
  note = note ? note + ' / alerte firmware memoire critique' : 'alerte firmware memoire critique';
} else if (requestedStatus === 'WARNING' && level === 'INFO') {
  level = 'WARNING';
  note = note ? note + ' / statut firmware WARNING' : 'statut firmware WARNING';
}

const heap_kb = Math.round((heap / 1024) * 100) / 100;
const heap_eff_kb = Math.round((heap_effective / 1024) * 100) / 100;

let msgHeader;
if (level === 'INFO') msgHeader = '[INFO] ' + device + ' - heap ' + heap_kb + ' KB (' + event + ') - OK';
else if (level === 'WARNING') msgHeader = '[WARN] ' + device + ' - heap bas ' + heap_kb + ' KB - surveiller';
else if (level === 'CRITICAL') msgHeader = '[CRIT] ' + device + ' - heap ' + heap_kb + ' KB - sous seuil PROD';
else msgHeader = '[FATAL] ' + device + ' - heap ' + heap + ' B - RISQUE CRASH IMMEDIAT';

const msgDetails = '\nModule  : ' + device +
  '\nHeap    : ' + heap + ' B (' + heap_kb + ' KB)' +
  (heap_effective !== heap ? '\nEffectif: ' + heap_effective + ' B (' + heap_eff_kb + ' KB)' : '') +
  '\nMax bloc: ' + (max_block !== null ? max_block + ' B' : 'N/A') +
  '\nFrag    : ' + (frag_pct !== null ? frag_pct + '%' : 'N/A') +
  '\nEvent   : ' + event +
  '\nUptime  : ' + uptimeStr +
  '\nNiveau  : ' + level +
  (note ? '\nNote    : ' + note : '') +
  '\nHeure   : ' + timestamp;

const telegramMsg = msgHeader + '\n' + msgDetails;
const maxBlockSql = max_block !== null ? max_block : 'NULL';
const fragPctSql = frag_pct !== null ? frag_pct : 'NULL';
const noteSql = note ? sq + esc(note) + sq : 'NULL';

const sqlCreateTable = "CREATE TABLE IF NOT EXISTS heap_monitoring.heap_logs (id INT AUTO_INCREMENT PRIMARY KEY, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP, device VARCHAR(64), heap INT, heap_kb FLOAT, heap_effective INT, max_block INT, frag_pct TINYINT UNSIGNED, uptime BIGINT, event VARCHAR(32), level ENUM('INFO','WARNING','CRITICAL','FATAL'), note VARCHAR(128))";
const sqlInsert = 'INSERT INTO heap_monitoring.heap_logs (device, heap, heap_kb, heap_effective, max_block, frag_pct, uptime, event, level, note) VALUES (' +
  sq + esc(device) + sq + ', ' + heap + ', ' + heap_kb + ', ' + heap_effective + ', ' +
  maxBlockSql + ', ' + fragPctSql + ', ' + uptime + ', ' +
  sq + esc(event) + sq + ', ' + sq + level + sq + ', ' + noteSql + ')';

return [{ json: {
  type, alert: ['WARNING','CRITICAL','FATAL'].includes(level), device, heap, heap_kb, heap_effective, heap_eff_kb,
  max_block, frag_pct, uptime, uptimeStr,
  event, level, note, timestamp, telegramMsg, sqlCreateTable, sqlInsert
} }];

const staticData = $getWorkflowStaticData('global');
const data = $('Normalize & Compute Status').first().json;
const device = data.device;
const level = data.level;
const now = Date.now();

// FATAL : alerte inconditionnelle - bypass anti-spam
if (level === 'FATAL') {
  return [{ json: { ...data, canSend: true } }];
}

// Fenetres anti-spam par niveau
const windowWarning = 30 * 60 * 1000;
const windowCritical = 10 * 60 * 1000;
const windowMs = level === 'WARNING' ? windowWarning : windowCritical;

const lastAlertKey = 'lastAlert_' + level + '_' + device;
const lastAlert = staticData[lastAlertKey] || 0;

if (now - lastAlert < windowMs) {
  const waitSec = Math.round((windowMs - (now - lastAlert)) / 1000);
  return [{ json: { ...data, canSend: false, blockedSec: waitSec } }];
}

staticData[lastAlertKey] = now;
return [{ json: { ...data, canSend: true } }];
